119	+/* ===== Đoạn giới thiệu điện ảnh: tư thế camera (thuần) — D-045 ===== */
120	+export type InVec = [number, number, number];
121	+export interface InPose { pos: InVec; target: InVec }
122	+export interface InShot { from: InPose; to: InPose }
123	+
124	+/* smootherstep 6k⁵ − 15k⁴ + 10k³, kẹp [0, 1] */
125	+export function inEase(k: number): number {
126	+  const x = k < 0 ? 0 : k > 1 ? 1 : k;
127	+  return x * x * x * (x * (x * 6 - 15) + 10);
128	+}
129	+
130	+/* Ghi vào pos / target (không cấp phát), nội suy theo inEase(k) */
131	+export function inPose(shot: InShot, k: number, pos: InVec, target: InVec): void {
132	+  const e = inEase(k);
133	+  for (let j = 0; j < 3; j++) {
134	+    pos[j] = shot.from.pos[j] + (shot.to.pos[j] - shot.from.pos[j]) * e;
135	+    target[j] = shot.from.target[j] + (shot.to.target[j] - shot.from.target[j]) * e;
136	+  }
137	+}
138	+
139	+/* Quay pos quanh trục Y qua target một góc ang (rad), ghi tại chỗ */
140	+export function inOrbit(pos: InVec, target: InVec, ang: number): void {
141	+  const dx = pos[0] - target[0], dz = pos[2] - target[2], c = Math.cos(ang), s = Math.sin(ang);
142	+  pos[0] = target[0] + dx * c + dz * s;
143	+  pos[2] = target[2] - dx * s + dz * c;
144	+}
