151	+/* ===== Đoạn giới thiệu điện ảnh: đồng hồ nhịp (thuần, không import three / DOM) — D-045 ===== */
152	+export type InSceneId = 'welcome' | 'glider' | 'car' | 'bike' | 'walk' | 'daynight' | 'dragon' | 'swing' | 'finale';
153	+export interface InScene { id: InSceneId; chapter: number; dur: number }
154	+export interface InClock { i: number; t: number; paused: boolean; done: boolean }   // i: nhịp đang chạy; t: giây trong nhịp; done: nhịp cuối đã hết thời lượng
155	+
156	+export function inCreate(): InClock { return { i: 0, t: 0, paused: false, done: false }; }
157	+
158	+/* Trả chỉ số nhịp mới nếu vừa sang nhịp, không thì −1. Tạm dừng thì không đổi gì; nhịp cuối kẹp t ở dur, done = true */
159	+export function inAdvance(c: InClock, scenes: readonly InScene[], dt: number): number {
160	+  if (c.paused) return -1;
161	+  const last = scenes.length - 1;
162	+  if (c.i >= last) { c.t = Math.min(c.t + dt, scenes[last].dur); if (c.t >= scenes[last].dur) c.done = true; return -1; }
163	+  c.t += dt;
164	+  if (c.t < scenes[c.i].dur) return -1;
165	+  c.t -= scenes[c.i].dur; c.i++;
166	+  if (c.i >= last && c.t >= scenes[last].dur) { c.t = scenes[last].dur; c.done = true; }
167	+  return c.i;
168	+}
169	+
170	+export function inSeek(c: InClock, scenes: readonly InScene[], i: number): number {
171	+  c.i = Math.max(0, Math.min(scenes.length - 1, i | 0)); c.t = 0; c.done = false; return c.i;
172	+}
173	+
174	+/* Độ đục màn tối 0–1: đầu nhịp 1 → 0 trong fade (first: không), cuối nhịp 0 → 1 trong fade (last: không) */
175	+export function inFade(t: number, dur: number, fade: number, first: boolean, last: boolean): number {
176	+  let a = 0;
177	+  if (!first && t < fade) a = Math.max(a, 1 - t / fade);
178	+  if (!last && t > dur - fade) a = Math.max(a, 1 - (dur - t) / fade);
179	+  return Math.max(0, Math.min(1, a));
180	+}
181	+
182	+/* Mức đầy 0–1 của đoạn tiến trình thứ k: trước i là 1, sau i là 0, tại i là t / dur */
183	+export function inFill(c: InClock, scenes: readonly InScene[], k: number): number {
184	+  if (k < c.i) return 1;
185	+  if (k > c.i) return 0;
186	+  return Math.max(0, Math.min(1, c.t / scenes[k].dur));
187	+}
188	+
189	+export function inShould(a: { explore: boolean; test: boolean; introParam: string | null; stored: string | null; seen: boolean; forced: boolean; reducedMotion: boolean; saveData: boolean }): boolean {
190	+  if (a.explore) return false;
191	+  if (a.introParam === 'off') return false;
192	+  if (a.test) return a.introParam !== null;
193	+  if (a.forced) return true;
194	+  return a.stored !== 'off' && !a.seen && !a.reducedMotion && !a.saveData;
195	+}
